export function validateReviewCompletion(input: unknown): ReviewCompletion {
  const completion = reviewCompletionSchema.parse(input)
  if (completion.verdict === 'blocked' && completion.findings.length === 0)
    throw new Error('A blocked verdict must name the findings that caused it')
  if (completion.verdict === 'approved' && completion.findings.some(f => f.severity !== 'P2' && f.disposition !== 'resolved'))
    throw new Error('Approval cannot leave an unresolved P0/P1 finding')
  return completion
